// The atlas contains three painted fighters with a shared foot anchor. The
// other three intentionally retain the procedural renderer below as a fallback.
const FIGHTER_ART='data:image/webp;base64,';
const PAINTED_ROWS={lara:0,cloud:1,wukong:2};
const CELL_W=416,CELL_H=320,ANCHOR_X=208,ANCHOR_Y=300,PIXEL_SCALE=.6;
const ANIMATIONS={
 idle:{frames:[0,0,0,0],ticks:8},
 run:{frames:[1,2],ticks:6},
 jump:{frames:[1,2],ticks:8},
 attack:{frames:[0,4,3,0],ticks:4},
 hurt:{frames:[4,4],ticks:6},
 dash:{frames:[1,2],ticks:4},
 skill:{frames:[0,4,3,0],ticks:5},
 guard:{frames:[4,4],ticks:8},
 land:{frames:[0,0],ticks:4}
};
let fighterImage=null,fighterLoaded=false;
const ready=new Promise(resolve=>{
 if(typeof root.Image!=='function'){resolve(false);return;}
 const img=new root.Image();
 img.onload=()=>{fighterImage=img;fighterLoaded=true;resolve(true);};
 img.onerror=()=>resolve(false);
 img.src=FIGHTER_ART;
});
function resolveAnimation(f,t=0,ghost=false){
 let state='idle';const a=f.attack;
 if(f.guardStun>0&&f.block)state='guard';else if(f.stun)state='hurt';else if(f.dash||ghost&&f.animState==='dash')state='dash';
 else if(a)state=(a.name==='skill'||a.name==='ultimate')?'skill':'attack';
 else if(!ghost&&Number.isFinite(f.y)&&f.y<(root.Rift?.FLOOR??510)-1)state='jump';
 else if(f.block)state='guard';else if(Math.abs(f.vx||0)>1)state='run';else if(f.landTime)state='land';
 const clip=ANIMATIONS[state],tick=Number.isFinite(f.animTime)?f.animTime:t;
 let index=Math.floor(Math.max(0,tick)/clip.ticks)%clip.frames.length;
 if(a&&(state==='attack'||state==='skill')){
  const startup=Math.max(1,a.move?.startup||1),active=Math.max(1,a.move?.active||1),at=Math.max(0,a.t||0);
  index=at<startup*.45?0:at<startup?1:at<startup+active?2:3;
 }
 if(state==='jump'&&Number.isFinite(f.vy))index=f.vy<0?0:1;
 return {state,index,cell:clip.frames[index]};
}
function drawFighter(context,f,t=0,ghost=false){
 const animation=resolveAnimation(f,t,ghost),row=PAINTED_ROWS[f.hero];
 if(!fighterLoaded||row===undefined){
  // Match the painted characters' height while preserving the foot anchor.
  const tick=Number.isFinite(f.animTime)?f.animTime:t;
  const stepped=animation.state==='run'?(Math.floor(tick/6)%2?15:5):t;
  context.save();context.translate(f.x||0,f.y||0);context.scale(1.2,1.2);
  if(animation.state==='jump')context.rotate((f.dir||1)*-.10);
  if(animation.state==='land')context.scale(1.04,.96);
  draw(context,{...f,x:0,y:0},stepped,ghost);context.restore();return;
 }
 context.save();context.translate(f.x||0,f.y||0);context.scale(f.dir||1,1);
 if(animation.state==='idle'&&!ghost)context.scale(1,[1,.994,.988,.994][animation.index]);
 if(animation.state==='land')context.scale(1.035,.965);
 if(animation.state==='dash')context.rotate(.045);
 if(f.flash>0&&!ghost&&'filter' in context)context.filter='brightness(1.8) saturate(.65)';
 const x=-ANCHOR_X*PIXEL_SCALE,y=-ANCHOR_Y*PIXEL_SCALE;
 context.drawImage(fighterImage,animation.cell*CELL_W,row*CELL_H,CELL_W,CELL_H,
  x,y,CELL_W*PIXEL_SCALE,CELL_H*PIXEL_SCALE);
 context.restore();
}
root.RiftFighters={draw:drawFighter,ready,resolveAnimation,ANIMATIONS,PAINTED_ROWS};

